[standards/application/api/STD-APP-API-003-internal-external-api-guidelines.md#3341-api-gateway-pattern]

##### 3.3.4.1 API Gateway Pattern

The most common hybrid approach using an API gateway to route and transform requests:

```yaml
architecture_overview:
    pattern: 'API Gateway with Dual Endpoints'
    components:
        - api_gateway: 'Routes requests and applies different policies'
        - business_service: 'Core business logic shared between endpoints'
        - data_transformation: 'Filters and shapes data based on consumer type'
        - security_layer: 'Different auth/authz for internal vs external'
```

```javascript
// API Gateway Configuration Example (Express.js with middleware)
const express = require('express');
const { createProxyMiddleware } = require('http-proxy-middleware');

const app = express();

// Shared business service proxy configuration
const businessServiceProxy = createProxyMiddleware({
    target: 'http://business-service:8080',
    changeOrigin: true,
    pathRewrite: (path, req) => {
        // Add context about the consumer type
        req.headers['x-consumer-type'] = req.isInternal ? 'internal' : 'external';
        return path;
    },
});

// Internal API route with enterprise authentication
app.use(
    '/internal/api/v1/*',
    authenticateService,
    authorizeInternalAccess,
    (req, res, next) => {
        req.isInternal = true;
        next();
    },
    businessServiceProxy
);

// External API route with customer authentication
app.use(
    '/api/v1/*',
    authenticateCustomer,
    rateLimitByCustomer,
    validateExternalRequest,
    (req, res, next) => {
        req.isInternal = false;
        next();
    },
    businessServiceProxy
);
```

