[standards/application/api/STD-APP-API-003-internal-external-api-guidelines.md#3343-shared-service-with-context-aware-responses]

##### 3.3.4.3 Shared Service with Context-Aware Responses

Single service that adapts responses based on consumer context:

```javascript
// Shared service with context-aware filtering
class UserProfileService {
    async getUserProfile(userId, requestContext) {
        const fullProfile = await this.repository.getUser(userId);

        // Apply different data filters based on consumer type
        switch (requestContext.consumerType) {
            case 'internal':
                return this.getInternalView(fullProfile, requestContext);
            case 'external':
                return this.getExternalView(fullProfile, requestContext);
            case 'partner':
                return this.getPartnerView(fullProfile, requestContext);
            default:
                throw new Error('Unknown consumer type');
        }
    }

    getInternalView(profile, context) {
        // Return complete internal data
        return {
            ...profile,
            auditInfo: profile.auditInfo,
            internalNotes: profile.internalNotes,
            systemMetadata: profile.systemMetadata,
        };
    }

    getExternalView(profile, context) {
        // Validate customer can access this profile
        if (context.customerId !== profile.id && !context.hasAdminRole) {
            throw new UnauthorizedError('Cannot access other customer profiles');
        }

        // Return customer-safe data only
        return {
            id: profile.id,
            name: profile.name,
            email: profile.email,
            preferences: profile.preferences,
            createdDate: profile.createdDate,
        };
    }

    getPartnerView(profile, context) {
        // Return partner-specific data based on partnership agreements
        const allowedFields = this.getPartnerAllowedFields(context.partnerId);
        return this.filterByAllowedFields(profile, allowedFields);
    }
}
```

