#### 4.3.2 External API Example - Customer Account Management

```yaml
# External API Classification
api_name: 'Customer Account Management API'
classification: 'External'
justification: |
    - Consumers: Customer mobile apps, web portals, third-party financial tools
    - Data sensitivity: Customer financial information
    - Network access: Public internet via mobile/web applications
    - Authentication: Customer credentials with OAuth 2.0

security_implementation:
    authentication: 'OAuth 2.0 with customer credentials'
    authorization: 'Customer-scoped access with resource-level permissions'
    network: 'Public internet with WAF and DDoS protection'
    additional: 'Rate limiting, input validation, PII protection'

documentation_location: 'Public developer portal at developers.company.com'
```

```javascript
// Implementation example
const express = require('express');
const { authenticateCustomer, rateLimitCustomer, validateInput } = require('./middleware');

app.get(
    '/api/v1/customers/:customerId/accounts',
    authenticateCustomer,
    rateLimitCustomer(100, '15min'), // 100 requests per 15 minutes
    validateInput.customerId,
    async (req, res) => {
        try {
            // Ensure customer can only access their own data
            if (req.customer.id !== req.params.customerId) {
                return res.status(403).json({
                    error: 'Access denied',
                    message: 'You can only access your own account information',
                });
            }

            const accounts = await getCustomerAccounts(req.params.customerId);

            // Filter sensitive information for external consumption
            const filteredAccounts = accounts.map((account) => ({
                id: account.id,
                type: account.type,
                balance: account.balance,
                status: account.status,
                lastActivity: account.lastActivity,
                // Exclude internal fields like internalNotes, riskScore, etc.
            }));

            res.json({
                status: 'success',
                data: filteredAccounts,
                meta: {
                    customerId: req.params.customerId,
                    timestamp: new Date().toISOString(),
                    version: 'v1',
                },
            });
        } catch (error) {
            // Log detailed error internally but return generic error to customer
            logger.error('Account retrieval failed', {
                customerId: req.params.customerId,
                error: error.message,
            });

            res.status(500).json({
                error: 'Service unavailable',
                message: 'Unable to retrieve account information at this time',
                supportId: generateSupportId(),
            });
        }
    }
);
```

