[standards/application/api/STD-APP-API-003-internal-external-api-guidelines.md#4331-api-gateway-pattern---product-catalog]

##### 4.3.3.1 API Gateway Pattern - Product Catalog

For APIs that need both internal and external access, implement an API Gateway pattern with shared business logic:

```yaml
# Hybrid API Implementation - Product Catalog
api_name: 'Product Catalog API'
pattern: 'API Gateway with Dual Consumer Support'
business_justification: |
    - Internal teams need full product data including cost, supplier, and inventory details
    - External customers need public product information without sensitive business data
    - Shared product management logic reduces development and maintenance overhead

architecture:
    shared_service: 'ProductCatalogService handles all business logic'
    api_gateway: 'Routes and transforms requests based on consumer type'
    data_filtering: 'Context-aware data transformation based on access level'
```

```javascript
// Enhanced API Gateway Implementation
const express = require('express');
const rateLimit = require('express-rate-limit');
const { ProductService, DataTransformer } = require('./services');

const app = express();
const productService = new ProductService();

// Shared middleware for request context
const addRequestContext = (consumerType) => (req, res, next) => {
    req.context = {
        consumerType,
        requestId: req.headers['x-request-id'] || generateRequestId(),
        timestamp: new Date(),
        userId: req.user?.id,
        serviceId: req.service?.id,
    };
    next();
};

// Internal API endpoint - Full data access
app.get(
    '/internal/api/v1/products/:productId',
    authenticateService,
    authorizeInternalAccess(['product:read', 'inventory:read']),
    addRequestContext('internal'),
    async (req, res) => {
        try {
            const product = await productService.getProductById(req.params.productId, req.context);

            const transformedData = DataTransformer.transform(product, {
                ...req.context,
                includeInternalData: true,
                includeAuditInfo: true,
            });

            res.json({
                status: 'success',
                data: transformedData,
                meta: {
                    requestId: req.context.requestId,
                    serviceVersion: process.env.SERVICE_VERSION,
                },
            });
        } catch (error) {
            handleInternalError(error, req, res);
        }
    }
);

// External API endpoint - Filtered data access
app.get(
    '/api/v1/products/:productId',
    authenticateCustomer,
    rateLimit({
        windowMs: 15 * 60 * 1000, // 15 minutes
        max: 100, // limit each customer to 100 requests per windowMs
        keyGenerator: (req) => req.customer.id,
        message: 'Too many requests, please try again later.',
    }),
    addRequestContext('external'),
    async (req, res) => {
        try {
            const product = await productService.getProductById(req.params.productId, req.context);

            const transformedData = DataTransformer.transform(product, {
                ...req.context,
                includeInternalData: false,
                customerId: req.customer.id,
            });

            res.json({
                status: 'success',
                data: transformedData,
                meta: {
                    requestId: req.context.requestId,
                    version: 'v1',
                    timestamp: req.context.timestamp,
                },
            });
        } catch (error) {
            handleExternalError(error, req, res);
        }
    }
);

// Partner API endpoint - Partner-specific data access
app.get(
    '/partner/api/v1/products/:productId',
    authenticatePartner,
    validatePartnerAccess,
    addRequestContext('partner'),
    async (req, res) => {
        try {
            const product = await productService.getProductById(req.params.productId, req.context);

            const partnerAgreement = await getPartnerAgreement(req.partner.id);
            const transformedData = DataTransformer.transform(product, {
                ...req.context,
                partnerAgreement,
                includePartnerData: true,
            });

            res.json({
                status: 'success',
                data: transformedData,
                partner: {
                    id: req.partner.id,
                    agreement: partnerAgreement.level,
                },
            });
        } catch (error) {
            handlePartnerError(error, req, res);
        }
    }
);

// Enhanced Data Transformer
class DataTransformer {
    static transform(product, context) {
        const baseProduct = {
            id: product.id,
            name: product.name,
            description: product.description,
        };

        switch (context.consumerType) {
            case 'internal':
                return this.getInternalView(product, context);
            case 'external':
                return this.getExternalView(product, context);
            case 'partner':
                return this.getPartnerView(product, context);
            default:
                return baseProduct;
        }
    }

    static getInternalView(product, context) {
        return {
            ...product,
            internalCost: product.cost,
            supplierInfo: product.supplier,
            inventoryDetails: {
                onHand: product.inventory.quantity,
                reserved: product.inventory.reserved,
                available: product.inventory.available,
                reorderPoint: product.inventory.reorderPoint,
            },
            auditInfo: context.includeAuditInfo
                ? {
                      createdBy: product.audit.createdBy,
                      lastModified: product.audit.lastModified,
                      version: product.audit.version,
                  }
                : undefined,
        };
    }

    static getExternalView(product, context) {
        // Validate customer can access this product
        if (product.restricted && !this.customerCanAccess(product, context.customerId)) {
            throw new ForbiddenError('Product not available');
        }

        return {
            id: product.id,
            name: product.name,
            description: product.description,
            price: product.publicPrice,
            availability: product.inventory.available > 0 ? 'in-stock' : 'out-of-stock',
            images: product.images.filter((img) => img.public),
            categories: product.categories,
            specifications: product.publicSpecs,
        };
    }

    static getPartnerView(product, context) {
        const { partnerAgreement } = context;
        const baseView = this.getExternalView(product, context);

        // Add partner-specific data based on agreement level
        if (partnerAgreement.level >= 'standard') {
            baseView.wholesalePrice = product.wholesalePrice;
            baseView.minimumOrderQuantity = product.moq;
        }

        if (partnerAgreement.level >= 'premium') {
            baseView.inventory = {
                available: product.inventory.available,
                expectedRestockDate: product.inventory.expectedRestock,
            };
        }

        return baseView;
    }
}
```

