##### 4.3.3.2 Backend for Frontend (BFF) Pattern - Order Management

Different optimized backends for internal operations and customer-facing applications:

```yaml
# BFF Pattern Implementation
api_name: 'Order Management API'
pattern: 'Backend for Frontend with Shared Services'
use_case: |
    - Internal order management system needs full order lifecycle access
    - Customer mobile app needs order status and basic details only
    - Customer service portal needs moderate access for support operations

services:
    order_core_service: 'Handles all order business logic and data persistence'
    internal_bff: 'Optimized for internal operational requirements'
    customer_bff: 'Optimized for customer self-service requirements'
    support_bff: 'Optimized for customer service representative needs'
```

```javascript
// Internal BFF - Full operational access
class InternalOrderBFF {
    constructor(orderService, auditService, inventoryService) {
        this.orderService = orderService;
        this.auditService = auditService;
        this.inventoryService = inventoryService;
    }

    async getOrderDetails(orderId, context) {
        const order = await this.orderService.getOrderById(orderId);
        const auditTrail = await this.auditService.getOrderAudit(orderId);
        const inventoryImpact = await this.inventoryService.getOrderImpact(orderId);

        return {
            ...order,
            internalDetails: {
                cost: order.internalCost,
                margin: order.margin,
                supplierInfo: order.supplierDetails,
                shippingCost: order.actualShippingCost,
            },
            auditTrail: auditTrail.entries,
            inventoryImpact: inventoryImpact,
            systemMetadata: {
                processingTime: order.processingMetrics,
                errorHistory: order.errorLog,
                integrationStatus: order.integrationStatus,
            },
        };
    }

    async processOrderOperation(orderId, operation, context) {
        // Internal operations can perform any action
        const validOperations = [
            'cancel',
            'refund',
            'expedite',
            'hold',
            'modify',
            'split',
            'merge',
            'investigate',
        ];

        if (!validOperations.includes(operation.type)) {
            throw new ValidationError(`Invalid operation: ${operation.type}`);
        }

        const result = await this.orderService.processOperation(orderId, operation, context);
        await this.auditService.logOperation(orderId, operation, context.userId);

        return result;
    }
}

// Customer BFF - Customer-focused and secure
class CustomerOrderBFF {
    constructor(orderService, notificationService) {
        this.orderService = orderService;
        this.notificationService = notificationService;
    }

    async getOrderDetails(orderId, customerId) {
        // Validate customer owns this order
        const order = await this.orderService.getOrderById(orderId);
        if (order.customerId !== customerId) {
            throw new ForbiddenError('Order not found');
        }

        // Return customer-appropriate view
        return {
            id: order.id,
            orderNumber: order.publicOrderNumber,
            status: this.translateStatusForCustomer(order.internalStatus),
            items: order.items.map((item) => ({
                id: item.id,
                name: item.name,
                quantity: item.quantity,
                price: item.publicPrice,
                image: item.primaryImage,
            })),
            shipping: {
                address: order.shippingAddress,
                method: order.shippingMethod.displayName,
                estimatedDelivery: order.estimatedDelivery,
                trackingNumber: order.trackingNumber,
            },
            totals: {
                subtotal: order.subtotal,
                tax: order.tax,
                shipping: order.publicShippingCost,
                total: order.total,
            },
            timeline: this.buildCustomerTimeline(order.statusHistory),
        };
    }

    async requestOrderAction(orderId, action, customerId) {
        // Customers can only perform limited actions
        const allowedActions = ['cancel', 'return', 'track', 'contact_support'];

        if (!allowedActions.includes(action.type)) {
            throw new ValidationError('Action not allowed');
        }

        const order = await this.orderService.getOrderById(orderId);
        if (order.customerId !== customerId) {
            throw new ForbiddenError('Order not found');
        }

        // Process customer-initiated actions with appropriate business rules
        const result = await this.orderService.processCustomerAction(orderId, action);
        await this.notificationService.notifyCustomer(customerId, 'order_action', result);

        return {
            status: 'success',
            message: this.getCustomerFriendlyMessage(action.type, result),
            nextSteps: this.getNextSteps(action.type, result),
        };
    }

    translateStatusForCustomer(internalStatus) {
        const statusMap = {
            payment_processing: 'Processing',
            inventory_check: 'Processing',
            fulfillment_queue: 'Preparing',
            picked: 'Preparing',
            packed: 'Ready to Ship',
            shipped: 'Shipped',
            out_for_delivery: 'Out for Delivery',
            delivered: 'Delivered',
            cancelled: 'Cancelled',
            returned: 'Returned',
        };
        return statusMap[internalStatus] || 'Processing';
    }
}

// API Gateway routing for BFF pattern
app.get('/internal/api/v1/orders/:orderId', authenticateService, async (req, res) => {
    const bff = new InternalOrderBFF(orderService, auditService, inventoryService);
    const order = await bff.getOrderDetails(req.params.orderId, req.context);
    res.json({ status: 'success', data: order });
});

app.get('/api/v1/orders/:orderId', authenticateCustomer, async (req, res) => {
    const bff = new CustomerOrderBFF(orderService, notificationService);
    const order = await bff.getOrderDetails(req.params.orderId, req.customer.id);
    res.json({ status: 'success', data: order });
});
```

