##### 4.3.3.4 Hybrid API Monitoring and Observability

```javascript
// Enhanced monitoring for hybrid APIs
const { createLogger, format, transports } = require('winston');
const prometheus = require('prom-client');

// Consumer-specific metrics
const apiRequestDuration = new prometheus.Histogram({
    name: 'api_request_duration_seconds',
    help: 'Duration of API requests in seconds',
    labelNames: ['method', 'route', 'status_code', 'consumer_type'],
    buckets: [0.1, 0.5, 1, 2, 5],
});

const apiRequestCount = new prometheus.Counter({
    name: 'api_requests_total',
    help: 'Total number of API requests',
    labelNames: ['method', 'route', 'status_code', 'consumer_type'],
});

// Context-aware logging middleware
const loggingMiddleware = (req, res, next) => {
    const startTime = Date.now();

    const logger = createLogger({
        format: format.combine(format.timestamp(), format.json()),
        defaultMeta: {
            requestId: req.context.requestId,
            consumerType: req.context.consumerType,
            userId: req.context.userId || req.context.serviceId,
            route: req.route?.path,
            method: req.method,
        },
        transports: [
            new transports.Console(),
            new transports.File({
                filename: `logs/api-${req.context.consumerType}.log`,
            }),
        ],
    });

    req.logger = logger;

    res.on('finish', () => {
        const duration = (Date.now() - startTime) / 1000;

        // Record metrics
        apiRequestDuration
            .labels(
                req.method,
                req.route?.path || req.path,
                res.statusCode,
                req.context.consumerType
            )
            .observe(duration);

        apiRequestCount
            .labels(
                req.method,
                req.route?.path || req.path,
                res.statusCode,
                req.context.consumerType
            )
            .inc();

        // Log request completion
        logger.info('Request completed', {
            statusCode: res.statusCode,
            duration: duration,
            responseSize: res.get('content-length'),
        });
    });

    next();
};

// Consumer-specific health checks
app.get('/internal/health', authenticateService, (req, res) => {
    res.json({
        status: 'healthy',
        services: {
            database: 'connected',
            cache: 'connected',
            messageQueue: 'connected',
        },
        internal: {
            memoryUsage: process.memoryUsage(),
            uptime: process.uptime(),
        },
    });
});

app.get('/health', (req, res) => {
    res.json({
        status: 'healthy',
        version: process.env.API_VERSION,
        timestamp: new Date().toISOString(),
    });
});
```
